(function(){const revertDelay=1500;function setStatus(button,text){if(!button){return}const originalText=button.getAttribute('data-original-text');if(!originalText){button.setAttribute('data-original-text',button.textContent.trim())}button.textContent=text;button.disabled=true;setTimeout(()=>{button.textContent=button.getAttribute('data-original-text');button.disabled=false},revertDelay)}document.addEventListener('click',async function(event){const button=event.target.closest('[data-copy-identifier]');if(!button){return}const cardForm=button.closest('form');if(!cardForm){return}const identifierInput=cardForm.querySelector('input[name="identifier"]');if(!identifierInput){return}const identifier=identifierInput.value;if(!identifier){return}try{await navigator.clipboard.writeText(identifier);setStatus(button,'Copied!')}catch(err){console.warn('Failed to copy identifier',err);setStatus(button,'Failed')}})})();